          criteria: ['The result comes from a chained filter() -> map() -> reduce() with no manual for loop and accumulator', 'The program prints exactly "Reduced Total: 56" (2*2 + 4*4 + 6*6)'],
          hint: '[1,2,3,4,5,6].filter(n => n % 2 === 0).map(n => n * n).reduce((a, b) => a + b, 0)',
